    "Modify Features": "Modificar funciones",
    "Discord is known to punish users of scripts or plugins that modify the completion of Quests. Modifying the completion of Quests is against Discord's": "Se sabe que Discord castiga a quienes usan scripts o plugins que modifican la finalización de misiones. Hacerlo va en contra de los",
    "Terms of Service": "Términos del servicio",
    "The punishment consists of a temporary or permanent loss of access to Quests and their rewards.": "El castigo es la pérdida temporal o permanente del acceso a las misiones y sus recompensas.",
    "The punishment also consists of an account standing violation which lasts 2 years per violation.": "El castigo también incluye una infracción en el estado de la cuenta que dura 2 años por cada una.",
    "Due to the various methods Discord uses to track users, there's no way to realistically evade detection. If you proceed, understand that Discord likely will detect your use at some point.": "Por los distintos métodos que usa Discord para rastrear, no hay forma realista de evitar que te detecten. Si continúas, ten en cuenta que Discord probablemente lo detectará en algún momento.",
    "Use the following toggle to access potentially dangerous settings at your own risk.": "Usa el siguiente interruptor para acceder a ajustes potencialmente peligrosos bajo tu propia responsabilidad.",
    "Hide Non Auto-Completable Quests:": "Ocultar misiones que no se pueden autocompletar:",
    "Accelerate Video Quest auto-completion:": "Acelerar el autocompletado de misiones de vídeo:",
    "Prevent Video Quests from pausing when losing focus:": "Evitar que las misiones de vídeo se pausen al perder el foco:",
    "Make some mobile-only Video Quests completable on desktop:": "Permitir completar en escritorio algunas misiones de vídeo solo para móvil:",
    "Auto-complete Quests simultaneously rather than sequentially:": "Autocompletar misiones a la vez en lugar de una tras otra:",
    "Resume interrupted auto-completions after a reload or restart:": "Reanudar autocompletados interrumpidos tras recargar o reiniciar:",
