    "Discord has implemented a Quest Ban system which will temporarily or permanently limit your access to completing Quests and claiming their rewards if you are found to be completing them through unofficial means. Modifying the completion of Quests is against their": "Discord ha implantado un sistema de baneo de misiones que limita temporal o permanentemente el acceso a completarlas y reclamar recompensas si detecta que lo haces por medios no oficiales. Modificar la finalización de misiones va contra sus",
    "The punishment appears limited to loss of access to Quests and their rewards, but Discord may escalate at any time.": "El castigo parece limitarse a perder el acceso a misiones y recompensas, pero Discord puede endurecerlo en cualquier momento.",
    "Due to the various methods Discord uses to track users, there's no way to realistically evade detection. If you proceed, understand that Discord likely will detect it at some point.": "Por los distintos métodos que usa Discord para rastrear, no hay forma realista de evitar que te detecten. Si continúas, ten en cuenta que probablemente lo detectará en algún momento.",
    "Discord has begun punishing users of scripts and plugins that modify the completion of Quests. Modifying the completion of Quests is against their": "Discord ha empezado a castigar a quienes usan scripts y plugins que modifican la finalización de misiones. Hacerlo va contra sus",
