    "Blocked Users": "Usuarios bloqueados",
    "Display your currently playing audiobooks as Discord Rich Presence. Requires your AudioBookShelf server URL, username, and password.": "Muestra los audiolibros que escuchas como Rich Presence de Discord. Requiere la URL de tu servidor de AudioBookShelf, tu usuario y tu contraseña.",
    "Connects to tosu via WebSocket on port 24050. No configuration needed, just make sure tosu is running alongside osu!.": "Se conecta a tosu por WebSocket en el puerto 24050. No hay que configurar nada, solo asegúrate de que tosu está abierto junto a osu!.",
    "Show what you're currently listening to via stats.fm. Requires your listening history to be public.": "Muestra lo que escuchas ahora mediante stats.fm. Tu historial de escucha debe ser público.",
    "stats.fm username": "Usuario de stats.fm",
    "Show what you're playing on Jellyfin. To get your API key: open your Jellyfin web UI, press F12 to open Developer Tools, go to the Network tab, look for requests to your server, find the Authorization header (Ctrl+F to search), and You need the part from Token='this'. Your user ID can be found in your profile page URL.": "Muestra lo que ves en Jellyfin. Para obtener la clave de API: abre la web de Jellyfin, pulsa F12 para abrir las herramientas de desarrollo, ve a la pestaña Red, busca las peticiones a tu servidor, encuentra la cabecera Authorization (Ctrl+F para buscar) y copia la parte de Token='esto'. Tu ID de usuario está en la URL de tu perfil.",
    "User ID from profile URL": "ID de usuario de la URL del perfil",
    "{name} on Jellyfin": "{name} en Jellyfin",
    "Discord rich presence for Gensokyo Radio. Just enable it and listen!": "Rich Presence de Discord para Gensokyo Radio. ¡Actívalo y escucha!",
    "Show what you're currently listening to via Navidrome.": "Muestra lo que escuchas ahora mediante Navidrome.",
    "Navidrome Server URL (must be a public domain, e.g. https://navidrome.example.com).": "URL del servidor de Navidrome (debe ser un dominio público, p. ej. https://navidrome.example.com).",
    "Navidrome username.": "Usuario de Navidrome.",
    "Navidrome password.": "Contraseña de Navidrome.",
    "Optional Discord Application Client ID.": "ID de cliente de aplicación de Discord opcional.",
    "Optional: Provide your own Last.fm API Key (leaves default if empty).": "Opcional: usa tu propia clave de API de Last.fm (si está vacío se usa la predeterminada).",
    "Which type of activity to display.": "Qué tipo de actividad mostrar.",
    "Show the state / details line contents in the member list": "Mostrar las líneas de estado y detalles en la lista de miembros",
    "Hide Rich Presence when music is paused (instead of showing a stopwatch)": "Ocultar el Rich Presence al pausar la música (en lugar de mostrar un cronómetro)",
