    // Control Center, Theme Studio, Diagnostics and What's New
    "What's new in Endcord {version}": "Novedades de Endcord {version}",
    "Endcord updated to {version}": "Endcord se actualizó a {version}",
    "See what's new": "Ver novedades",
    "Endcord is easier to reach, easier to make your own, and open about what it's doing.": "Endcord ahora es más fácil de alcanzar y de personalizar, y muestra con claridad lo que hace.",
    "Control Center": "Centro de control",
    "The panda in the title bar now opens your themes, memory use and settings in one place.": "El panda de la barra de título ahora reúne tus temas, el uso de memoria y los ajustes en un solo lugar.",
    "Theme Studio": "Estudio de temas",
    "Pick a color and Discord changes as you drag, with no code. Export it when you like the result.": "Elige un color y Discord cambia mientras arrastras, sin código. Expórtalo cuando te guste el resultado.",
    "Diagnostics": "Diagnóstico",
    "See how long each plugin took to start and how much memory Discord uses, measured on your PC.": "Mira cuánto tardó cada plugin en iniciarse y cuánta memoria usa Discord, medido en tu PC.",
    "Security status": "Estado de seguridad",
    "Endcord checks its release signature and installed files, and shows you the result.": "Endcord comprueba la firma de la versión y los archivos instalados, y te muestra el resultado.",
