    "{count} on": "{count} activos",
    "Active When": "Cuándo se activa",
    "Given back this session, measured after each cleanup": "Liberada en esta sesión, medida tras cada limpieza",
    "While you play, Discord redraws at 15 FPS and pauses its animations, so your game keeps more of your PC.": "Mientras juegas, Discord se redibuja a 15 FPS y pausa sus animaciones, así tu juego dispone de más recursos del PC.",
    "While you play, Discord redraws at 15 FPS by default instead of your monitor's full speed, pauses its animations and gives cached memory back. Video and streams keep their own speed.": "Mientras juegas, Discord se redibuja a 15 FPS por defecto en lugar de a la velocidad máxima del monitor, pausa sus animaciones y libera la memoria en caché. Los vídeos y las transmisiones mantienen su propia velocidad.",
    "How often Discord redraws its interface while Game Mode is active. Video and streams keep their own speed": "Con qué frecuencia Discord redibuja su interfaz mientras el modo juego está activo. Los vídeos y las transmisiones mantienen su propia velocidad",
    "When Game Mode takes effect": "Cuándo se aplica el modo juego",
    "While a game is running and Discord is in the background": "Mientras un juego está abierto y Discord en segundo plano",
    "Whenever Discord is in the background": "Siempre que Discord esté en segundo plano",
    "No themes yet. Add a .css file and it shows up here.": "Aún no hay temas. Añade un archivo .css y aparecerá aquí.",
    "If Discord feels slow, try turning your themes and custom CSS off. The :has() selector is the most common cause.": "Si Discord va lento, prueba a desactivar tus temas y tu CSS personalizado. La causa más habitual es el selector :has().",
    "Blurs your DM list while Streamer Mode is on, and can turn it on when you share your screen.": "Difumina tu lista de MD con el modo streamer activo y puede activarlo al compartir pantalla.",
    "Release signature": "Firma de la versión",
    "Checked the next time Endcord can reach the update server.": "Se comprobará la próxima vez que Endcord llegue al servidor de actualizaciones.",
    "The current release is signed with Endcord's key. Checked {time}.": "La versión actual está firmada con la clave de Endcord. Comprobado {time}.",
    "The current release has no valid signature, so Endcord won't install it.": "La versión actual no tiene una firma válida, así que Endcord no la instalará.",
    "Installed files": "Archivos instalados",
    "Your files match the signed release exactly.": "Tus archivos coinciden exactamente con la versión firmada.",
    "Your files differ from the signed release. If you didn't change them, reinstall Endcord.": "Tus archivos difieren de la versión firmada. Si no los cambiaste, reinstala Endcord.",
    "Compared while you are on the latest release.": "Se comparan cuando tienes la última versión.",
    "Update recovery": "Recuperación de actualizaciones",
    "An update that fails to start three times is undone automatically.": "Una actualización que no arranca tres veces se deshace automáticamente.",
    "Starts with your next update, which keeps the version before it.": "Empieza con tu próxima actualización, que guarda la versión anterior.",
    "Something needs your attention": "Algo necesita tu atención",
    "Some checks are still waiting": "Algunas comprobaciones siguen pendientes",
    "All checks passed": "Todas las comprobaciones correctas",
    "Built in": "Integrado",
    "Only Discord's own pages can reach Endcord's native features.": "Solo las páginas de Discord pueden acceder a las funciones nativas de Endcord.",
    "Links from messages and other people can't make Endcord reach this PC or your local network.": "Los enlaces de mensajes y de otras personas no pueden hacer que Endcord acceda a este PC o a tu red local.",
    "API keys and passwords in plugin settings stay out of backups and cloud sync.": "Las claves de API y contraseñas de los plugins no entran en las copias de seguridad ni en la sincronización en la nube.",
