    // Safe mode, plugin health, profiles, snapshots, welcome and shortcuts
    "Endcord started in safe mode": "Endcord se inició en modo seguro",
    "As you asked, Endcord started with its plugins, themes and Custom CSS off. Nothing was changed: everything comes back when you restart.": "Como pediste, Endcord se inició con sus plugins, temas y CSS personalizado desactivados. No se cambió nada: todo vuelve al reiniciar.",
    "Discord didn't finish starting {count} times in a row, so this time Endcord started with its plugins, themes and Custom CSS off. Nothing was changed.": "Discord no terminó de iniciarse {count} veces seguidas, así que esta vez Endcord se inició con sus plugins, temas y CSS personalizado desactivados. No se cambió nada.",
    "Stay in safe mode": "Seguir en modo seguro",
    "Restart normally": "Reiniciar normalmente",
    "Turn off {count} and restart": "Desactivar {count} y reiniciar",
    "These plugins changed the part of Discord that crashed": "Estos plugins cambiaban la parte de Discord que falló",
    "These plugins were turned on since Discord last started fine": "Estos plugins se activaron después del último inicio correcto de Discord",
    "They're set to stay off. Switch back on any you're sure about.": "Se quedarán desactivados. Vuelve a activar los que te den confianza.",
    "Endcord couldn't tell which plugin it was. Turn off the ones you added most recently in the Plugins tab, then restart.": "Endcord no pudo saber qué plugin fue. Desactiva los más recientes en la pestaña Plugins y reinicia.",
    "Safe mode: Endcord's plugins, themes and Custom CSS are off until you restart.": "Modo seguro: los plugins, temas y CSS personalizado de Endcord están desactivados hasta que reinicies.",
    "Plugin health": "Estado de los plugins",
    "Discord changed code these plugins rely on, so part of what they do may not work until Endcord updates them. Everything else they do keeps working.": "Discord cambió código del que dependen estos plugins, así que parte de lo que hacen puede no funcionar hasta que Endcord los actualice. Todo lo demás sigue funcionando.",
    "{count} changes didn't apply": "{count} cambios no se aplicaron",
    "Every plugin's changes applied on this version of Discord, so far this session.": "En esta sesión, hasta ahora, los cambios de todos los plugins se aplicaron en esta versión de Discord.",
    "Safe mode": "Modo seguro",
    "Discord is running in safe mode right now: Endcord's plugins, themes and Custom CSS are off. Restart to bring them back.": "Discord está en modo seguro ahora mismo: los plugins, temas y CSS personalizado de Endcord están desactivados. Reinicia para recuperarlos.",
    "Starts Discord once with Endcord's plugins, themes and Custom CSS off, to see whether one of them causes a problem. Endcord does this by itself when Discord fails to start three times in a row.": "Inicia Discord una vez con los plugins, temas y CSS personalizado de Endcord desactivados, para ver si alguno causa un problema. Endcord lo hace solo cuando Discord no logra iniciarse tres veces seguidas.",
    "Restart in safe mode": "Reiniciar en modo seguro",
